/* AP United States Government and Politics, Unit 2: Interactions Among Branches of Government. Original teaching and practice
   aligned to the topics of the College Board's AP U.S. Government and Politics Course and Exam Description: 2.1 Congress: The
   Senate and the House of Representatives, 2.2 Structures, Powers, and Functions of Congress, 2.3 Congressional Behavior,
   2.4 Roles and Powers of the President, 2.5 Checks on the Presidency, 2.6 Expansion of Presidential Power, 2.7 Presidential
   Communication, 2.8 The Judicial Branch, 2.9 Legitimacy of the Judicial Branch, 2.10 The Court in Action,
   2.11 Checks on the Judicial Branch, 2.12 The Bureaucracy, 2.13 Discretionary and Rule-Making Authority, 2.14 Holding the
   Bureaucracy Accountable, 2.15 Policy and the Branches of Government.
   Required foundational documents and cases used here: Federalist No. 70, Federalist No. 78, Marbury v. Madison, Baker v. Carr
   and Shaw v. Reno. Federalist Nos. 70 and 78 are paraphrased; the only quotation is one sentence of Marbury v. Madison. Dates
   and facts are standard textbook civics, hedged where scholars differ, and no current officeholder or pending case is named.
   Scenarios marked fictional are teaching constructions. The unit is non-partisan: it explains how the institutions work. The
   pictures are drawn in code; any PixelLab art would be listed in ART_REQUESTS.md. */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const board=(title,lines)=>({t:'board',title,lines});
const table=(title,head,col,rows)=>({t:'setups',title,head,cols:[col],rows});
const flow=(title,labels,details)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((label,i)=>{const x=i*36;for(const [j,xy] of [[0,[x,15]],[1,[x+28,15]],[2,[x+28,27]],[3,[x,27]]])pts['ABCD'[j]+i]=xy;polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[x+14,7],text:details[i]});if(i<labels.length-1){pts['P'+i]=[x+29,21];pts['Q'+i]=[x+35,21];segs.push({v:`P${i}Q${i}`,arrows:1,col:i});}});return {t:'figure',title,view:[-3,103,0,34],pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join('')};};
/* a scaled timeline: the x axis is calendar years and labels alternate above and below the line */
const years=(title,span,events)=>{const pts={A:[span[0]+4,0],B:[span[1]-4,0]},notes=[];events.forEach(([y,text],i)=>{pts['E'+i]=[y,0];notes.push({at:[y,i%2?-4.5:4.5],text});});return {t:'figure',title,view:[span[0],span[1],-9,9],pts,hide:Object.keys(pts).join(''),dots:events.map((e,i)=>'E'+i).join(''),segs:[{v:'AB',arrows:1}],notes};};
/* labelled boxes in a row or grid: schematic only */
const regions=(title,boxes)=>{const pts={},polys=[],notes=[];boxes.forEach(([label,x0,y0,x1,y1,detail],i)=>{[[x0,y0],[x1,y0],[x1,y1],[x0,y1]].forEach((xy,j)=>{pts['ABCD'[j]+i]=xy;});polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[(x0+x1)/2,y0+2.4],text:detail});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes,dots:'',hide:Object.keys(pts).join('')};};
const growth=years('Growth of presidential power: 1788 to 1973 (years to scale)',[1770,1990],[[1788,'1788: Fed. 70'],[1939,'1939: EOP'],[1952,'1952: Steel case'],[1973,'1973: War Powers']]);
const chambers=regions('Who does what in Congress: schematic',[['House only',1,8,32,26,'revenue bills, impeach'],['Both',35,8,66,26,'laws, taxes, war'],['Senate only',69,8,99,26,'confirm, treaties, trial']]);
const courts=regions('The federal court system: schematic',[['Supreme Court: 9 justices',30,24,70,33,''],['Courts of appeals: 13 circuits',16,14,84,22,''],['District courts: 94 trial courts',2,3,98,11,'']]);
const agencies=regions('Four kinds of federal agency: schematic',[['Cabinet',1,8,24,26,'15 departments'],['Independent',26,8,49,26,'agencies'],['Regulatory',51,8,74,26,'commissions'],['Corporations',76,8,99,26,'government-owned']]);
const goPublic=flow('Going public',['President','The public','Congress'],['makes the case','shows support','feels pressure']);
const rulePath=flow('From statute to rule',['Statute','Proposed rule','Final rule'],['Congress writes','public comments','has legal force']);
